return items
  .map(it => {
    const name = (it.json['Name'] || '').toString().trim();
    const raw = (it.json['Target region'] || it.json['Location'] || '').toString().trim();
    const type = (it.json['Type'] || '').toString().trim();
    const ownership = (it.json['Ownership'] || '').toString().trim();

    const typeOfBook = (it.json['Type of book looking for'] || '').toString().trim();
    const availableCapital = (it.json['Available capital to Invest'] || '').toString().trim();
    const targetBookSize = (it.json['Target Book size'] || '').toString().trim();

    const customerLanguage = (it.json['Customer Language'] || '').toString().trim();
    const dealType = (it.json['Deal Type'] || '').toString().trim();
    const stage = (it.json['Stage'] || '').toString().trim();

    // ✅ NEW FIELDS
    const bookSize = (it.json['Book Size'] || '').toString().trim();
    const revenue = (it.json['Revenue'] || '').toString().trim();
    const askingPrice = (it.json['Asking Price'] || '').toString().trim();
    const bookType = (it.json['Book Type'] || '').toString().trim();
    const officeOrEmployeeDetails = (it.json['Office or Employee details'] || '').toString().trim();
    const limitations = (it.json['Limitations'] || '').toString().trim();
    const buyerType = (it.json['Buyer Type'] || '').toString().trim();

    // Clean location
    let loc = raw.split(/[\/;|]/)[0].replace(/\s+/g, ' ').trim();
    if (loc && !/USA|United States/i.test(loc)) loc = loc + ', USA';

    return {
      json: {
        name: name || null,
        location: loc || null,
        type: type || null,
        ownership: ownership || null,

        type_of_book: typeOfBook || null,
        available_capital: availableCapital || null,
        target_book_size: targetBookSize || null,

        customer_language: customerLanguage || null,
        deal_type: dealType || null,
        stage: stage || null,

        // ✅ new structured fields
        book_size: bookSize || null,
        revenue: revenue || null,
        asking_price: askingPrice || null,
        book_type: bookType || null,
        office_or_employee_details: officeOrEmployeeDetails || null,
        limitations: limitations || null,
        buyer_type: buyerType || null
      }
    };
  })
  .filter(it => it.json.name && it.json.location && it.json.type);

return items.map(item => {
  const geo = item.json.results?.[0]?.geometry;
  return {
    json: {
      name: item.json.name,
      location: item.json.location,
      lat: geo ? geo.lat : null,
      lng: geo ? geo.lng : null,
      type: item.json.type
    }
  }
});

// Ensure output is formatted for Leaflet + additional columns
return items.map(item => {
  return {
    json: {
      name: item.json.name || "Unknown",
      location: item.json.location || "N/A",
      lat: item.json.lat,
      lng: item.json.lng,
      type: item.json.type || "unspecified",
